// pako: deflate, then inflate, N kilobytes of generated bytes with repeats.
(function () {
  var pako = module.exports;
  if (N === 0) { console.log('RESULT 0'); return; }
  var size = N * 1024, data = new Uint8Array(size), next = lcg(11);
  for (var i = 0; i < size; i++) data[i] = (i % 61 < 40) ? (i * 7) & 63 : next() & 255;
  var packed = pako.deflate(data);
  var back = pako.inflate(packed);
  var h = mix(packed.length, back.length);
  for (var j = 0; j < back.length; j += 17) h = mix(h, back[j]);
  for (var k = 0; k < packed.length; k += 5) h = mix(h, packed[k]);
  console.log('RESULT ' + h);
})();
